    emailverified smallint DEFAULT 0 NOT NULL,
    lastworkspacegroupid integer,
    CONSTRAINT users_iauseaudio_check CHECK (((iauseaudio)::text = ANY ((ARRAY['semIA'::character varying, 'basico'::character varying, 'completo'::character varying])::text[]))),
