    CONSTRAINT users_iausetexto_check CHECK (((iausetexto)::text = ANY ((ARRAY['semIA'::character varying, 'basico'::character varying, 'completo'::character varying])::text[]))),
    CONSTRAINT users_iauseurl_check CHECK (((iauseurl)::text = ANY ((ARRAY['semIA'::character varying, 'basico'::character varying, 'completo'::character varying])::text[]))),
    CONSTRAINT users_iausevideo_check CHECK (((iausevideo)::text = ANY ((ARRAY['semIA'::character varying, 'basico'::character varying, 'completo'::character varying])::text[]))),
    CONSTRAINT users_role_check CHECK (((role)::text = ANY ((ARRAY['user'::character varying, 'admin'::character varying])::text[])))
);


